define(["core/notification"],function(Notification){function action(buttonId,link){var button=document.getElementById("btn-"+buttonId);var dialog=document.getElementById("confirm-"+buttonId);if(!button||!dialog){return}button.style.display="";button.addEventListener("click",function(event){event.preventDefault();var title=dialog.getAttribute("title")||"";var message="";var paragraph=dialog.querySelector("p");if(paragraph){message=paragraph.textContent}Notification.confirm(title,message,"Yes","No",function(){window.location.href=link})})}return{action:action}});